using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace Underwater.Editor {
public static class ReefClarityAudit {
 const string Scene="Assets/Scenes/Underwater_Realistic.unity",Output="Renders/ClarityOptimization/";
 const string Art="Assets/UnderwaterArt/ClarityOptimization/";
 public static void Apply(){
  var scene=EditorSceneManager.OpenScene(Scene);Directory.CreateDirectory(Output);Directory.CreateDirectory(Art);AssetDatabase.Refresh();OptimizeGeometry(true);
  var textures=UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsSortMode.None).SelectMany(r=>r.sharedMaterials).Where(m=>m).Distinct().SelectMany(m=>m.GetTexturePropertyNames().Select(n=>m.GetTexture(n))).OfType<Texture2D>().Select(AssetDatabase.GetAssetPath).Where(p=>p.StartsWith("Assets/UnderwaterArt/")).Distinct().ToArray();int changed=0;
  foreach(var path in textures){if(!(AssetImporter.GetAtPath(path) is TextureImporter imp))continue;if(imp.mipmapEnabled&&imp.filterMode==FilterMode.Trilinear&&imp.anisoLevel>=4&&imp.mipMapBias>=0)continue;imp.mipmapEnabled=true;imp.filterMode=FilterMode.Trilinear;imp.anisoLevel=Mathf.Max(4,imp.anisoLevel);imp.mipMapBias=Mathf.Max(0,imp.mipMapBias);imp.SaveAndReimport();changed++;}
  foreach(var group in UnityEngine.Object.FindObjectsByType<LODGroup>(FindObjectsSortMode.None))if(!group.GetComponent<ReefStableLod>())group.gameObject.AddComponent<ReefStableLod>();
  EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Debug.Log("CLARITY_APPLIED textureImporters="+changed);Validate();
 }
 public static void OptimizeGeometry(bool save=false){
  var cache=new Dictionary<Mesh,Mesh>();long removed=0;int meshes=0;foreach(var filter in UnityEngine.Object.FindObjectsByType<MeshFilter>(FindObjectsSortMode.None)){var r=filter.GetComponent<MeshRenderer>();if(!r||!filter.sharedMesh||r.GetComponentInParent<SeaLife>()||r.GetComponentInParent<SquidSwimmer>()||!r.sharedMaterials.Any(m=>m&&(m.shader.name=="Underwater/Reef Surface"||m.shader.name=="Underwater/Quest Reef")))continue;var source=filter.sharedMesh;if(!cache.TryGetValue(source,out var clean)){var vertices=source.vertices;clean=null;for(int sub=0;sub<source.subMeshCount;sub++){var triangles=source.GetTriangles(sub);var kept=new List<int>(triangles.Length);var seen=new HashSet<(Vector3,Vector3,Vector3)>();for(int i=0;i<triangles.Length;i+=3){var p=new[]{vertices[triangles[i]],vertices[triangles[i+1]],vertices[triangles[i+2]]};if(Vector3.Cross(p[1]-p[0],p[2]-p[0]).sqrMagnitude<1e-16f){removed++;continue;}Array.Sort(p,(a,b)=>a.x!=b.x?a.x.CompareTo(b.x):a.y!=b.y?a.y.CompareTo(b.y):a.z.CompareTo(b.z));if(!seen.Add((p[0],p[1],p[2]))){removed++;continue;}kept.Add(triangles[i]);kept.Add(triangles[i+1]);kept.Add(triangles[i+2]);}if(kept.Count!=triangles.Length){if(!clean)clean=UnityEngine.Object.Instantiate(source);clean.SetTriangles(kept,sub,false);}}
    if(clean){clean.name=source.name+" stable surface";meshes++;if(save){string path=Art+"Mesh_"+AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(source))+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){EditorUtility.CopySerialized(clean,old);UnityEngine.Object.DestroyImmediate(clean);clean=old;EditorUtility.SetDirty(clean);}else AssetDatabase.CreateAsset(clean,path);}}else clean=source;cache.Add(source,clean);
   }if(filter.sharedMesh!=clean){filter.sharedMesh=clean;EditorUtility.SetDirty(filter);}}
  Debug.Log("CLARITY_GEOMETRY uniqueMeshes="+meshes+" redundantTrianglesRemoved="+removed+" saved="+save);
 }
 public static void Validate(){
  EditorSceneManager.OpenScene(Scene);ReefCollisionValidation.Run();var sb=new StringBuilder();Snapshot(sb,"Repaired source");typeof(QuestReefBuild).GetMethod("OptimizeScene",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static).Invoke(null,null);Snapshot(sb,"Repaired Quest");
  if(QuestReefPerformance.EyeResolution<1||QuestReefPerformance.Samples<4)throw new Exception("Quest clarity settings missing");foreach(var group in UnityEngine.Object.FindObjectsByType<LODGroup>(FindObjectsSortMode.None))if(!group.GetComponent<ReefStableLod>())throw new Exception("Unstable detail group "+group.name);
  var test=new GameObject("LOD boundary test");var lod=test.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.1f,Array.Empty<Renderer>()),new LOD(.01f,Array.Empty<Renderer>())});var stable=test.AddComponent<ReefStableLod>();if(stable.Choose(.12f)!=0)throw new Exception("Near detail missing");for(int i=0;i<100;i++)if(stable.Choose(i%2==0?.098f:.102f)!=0)throw new Exception("LOD jitters around boundary");if(stable.Choose(.08f)!=1||stable.Choose(.13f)!=0||stable.Choose(.005f)!=-1)throw new Exception("LOD hysteresis failed");UnityEngine.Object.DestroyImmediate(test);
  foreach(string shader in new[]{"Underwater/Quest Reef","Underwater/Reef Surface"})if(ShaderUtil.ShaderHasError(Shader.Find(shader)))throw new Exception("Shader failed "+shader);CheckForcedCull();File.WriteAllText(Output+"After.txt",sb.ToString());Capture();Debug.Log("CLARITY_VALIDATED");
 }
 static void CheckForcedCull(){
  var target=new RenderTexture(32,32,24);target.Create();var cameraRoot=new GameObject("LOD raster test camera");var camera=cameraRoot.AddComponent<Camera>();camera.cullingMask=1<<31;camera.transform.position=new Vector3(0,0,-5);camera.orthographic=true;camera.orthographicSize=1;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.black;camera.targetTexture=target;var go=GameObject.CreatePrimitive(PrimitiveType.Quad);go.layer=31;var renderer=go.GetComponent<Renderer>();var material=new Material(Shader.Find("Unlit/Color"));material.color=Color.white;renderer.sharedMaterial=material;var group=go.AddComponent<LODGroup>();group.SetLODs(new[]{new LOD(.1f,new[]{renderer})});group.RecalculateBounds();var sample=new Texture2D(32,32,TextureFormat.RGB24,false);var previous=RenderTexture.active;
  try{group.ForceLOD(0);camera.Render();RenderTexture.active=target;sample.ReadPixels(new Rect(0,0,32,32),0,0);sample.Apply();float visible=sample.GetPixel(16,16).r;group.ForceLOD(group.lodCount);camera.Render();sample.ReadPixels(new Rect(0,0,32,32),0,0);sample.Apply();if(visible<.9f||sample.GetPixel(16,16).r>.1f)throw new Exception("Forced LOD culling did not match rendered result");Debug.Log("CLARITY_LOD_RASTER_CULL_PASSED");}finally{RenderTexture.active=previous;UnityEngine.Object.DestroyImmediate(sample);UnityEngine.Object.DestroyImmediate(material);UnityEngine.Object.DestroyImmediate(go);UnityEngine.Object.DestroyImmediate(cameraRoot);target.Release();UnityEngine.Object.DestroyImmediate(target);}
 }
 static void Capture(){
  var camera=Camera.main;camera.farClipPlane=160;camera.nearClipPlane=.035f;camera.fieldOfView=90;camera.aspect=1.2f;QualitySettings.lodBias=1.15f;QualitySettings.antiAliasing=4;QualitySettings.anisotropicFiltering=AnisotropicFiltering.ForceEnable;var atmosphere=UnityEngine.Object.FindFirstObjectByType<ReefAtmosphere>();
  for(int zone=0;zone<OceanWorld.Centers.Length;zone++){camera.transform.position=OceanWorld.Centers[zone]+Vector3.up*1.6f;camera.transform.rotation=Quaternion.identity;atmosphere.Apply(camera);foreach(var detail in UnityEngine.Object.FindObjectsByType<ReefFishDetail>(FindObjectsSortMode.None))detail.Select(camera.transform.position);ReefCorrectionAudit.Capture(camera,Output+"Habitat_"+zone+".png");}
 }
 public static void Inspect(){EditorSceneManager.OpenScene(Scene);Directory.CreateDirectory(Output);var report=new StringBuilder();Snapshot(report,"Source");typeof(QuestReefBuild).GetMethod("OptimizeScene",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static).Invoke(null,null);Snapshot(report,"Quest");File.WriteAllText(Output+"Before.txt",report.ToString());Debug.Log("CLARITY_INSPECTED");}
 static string Path(Transform t)=>t.parent?Path(t.parent)+"/"+t.name:t.name;
 static void Snapshot(StringBuilder report,string label){
  report.AppendLine(label+" quality="+QualitySettings.names[QualitySettings.GetQualityLevel()]+" mipLimit="+QualitySettings.globalTextureMipmapLimit+" AA="+QualitySettings.antiAliasing+" anisotropic="+QualitySettings.anisotropicFiltering);
  var members=new Dictionary<Renderer,List<(LODGroup,int)>>();foreach(var group in UnityEngine.Object.FindObjectsByType<LODGroup>(FindObjectsSortMode.None)){var levels=group.GetLODs();for(int i=0;i<levels.Length;i++)foreach(var r in levels[i].renderers){if(!r)continue;if(!members.ContainsKey(r))members[r]=new List<(LODGroup,int)>();members[r].Add((group,i));}}
  var renderers=UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None).Where(r=>r.enabled&&r.GetComponent<MeshFilter>()&&r.GetComponent<MeshFilter>().sharedMesh).ToArray();
  int multiply=0,duplicate=0;foreach(var r in renderers)if(members.TryGetValue(r,out var m)&&m.Select(p=>p.Item1).Distinct().Count()>1){multiply++;if(multiply<12)report.AppendLine("MULTIPLE_LOD "+Path(r.transform));}
  foreach(var group in renderers.GroupBy(r=>(r.GetComponent<MeshFilter>().sharedMesh,r.transform.localToWorldMatrix))){var list=group.ToArray();for(int i=0;i<list.Length;i++)for(int j=0;j<i;j++){bool exclusive=members.TryGetValue(list[i],out var first)&&members.TryGetValue(list[j],out var second)&&first.Any(a=>second.Any(b=>a.Item1==b.Item1&&a.Item2!=b.Item2));if(!exclusive){duplicate++;if(duplicate<20)report.AppendLine("OVERLAP "+Path(list[i].transform)+" vs "+Path(list[j].transform));}}}
  var textures=renderers.SelectMany(r=>r.sharedMaterials).Where(m=>m).Distinct().SelectMany(m=>m.GetTexturePropertyNames().Select(n=>m.GetTexture(n))).OfType<Texture2D>().Distinct().ToArray();foreach(var tex in textures){var path=AssetDatabase.GetAssetPath(tex);if(!(AssetImporter.GetAtPath(path) is TextureImporter imp))continue;var android=imp.GetPlatformTextureSettings("Android");report.AppendLine("TEXTURE "+path+" mip="+imp.mipmapEnabled+" filter="+imp.filterMode+" aniso="+imp.anisoLevel+" bias="+imp.mipMapBias+" stream="+imp.streamingMipmaps+" Android="+android.maxTextureSize+"/"+android.format);}
  long duplicateFaces=0;foreach(var mesh in renderers.Select(r=>r.GetComponent<MeshFilter>().sharedMesh).Distinct()){var seen=new HashSet<(Vector3,Vector3,Vector3)>();long count=0;var points=mesh.vertices;for(int sub=0;sub<mesh.subMeshCount;sub++){var triangles=mesh.GetTriangles(sub);for(int i=0;i<triangles.Length;i+=3){var v=new[]{points[triangles[i]],points[triangles[i+1]],points[triangles[i+2]]};if(Vector3.Cross(v[1]-v[0],v[2]-v[0]).sqrMagnitude<1e-16f)continue;Array.Sort(v,(a,b)=>a.x!=b.x?a.x.CompareTo(b.x):a.y!=b.y?a.y.CompareTo(b.y):a.z.CompareTo(b.z));if(!seen.Add((v[0],v[1],v[2])))count++;}}if(count>0){report.AppendLine("DUPLICATE_FACES "+mesh.name+" count="+count);duplicateFaces+=count;}}
  report.AppendLine(label+" SUMMARY renderers="+renderers.Length+" LODs="+UnityEngine.Object.FindObjectsByType<LODGroup>(FindObjectsSortMode.None).Length+" multipleOwners="+multiply+" overlappingInstances="+duplicate+" duplicateFaces="+duplicateFaces);
 }
}
}
